public static int mulAndCheck(int x, int y) {
    long m = ((long)x) * ((long)y);
    if (m < Integer.MIN_VALUE || m > Integer.MAX_VALUE) {
        throw new ArithmeticException("overflow: mul");
    }
    return (int)m;
}

